import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
public final class SourceWeaponTargetLifeDelta {
 static final String P=SourceWeaponTargetLifeMethods.P,N=SourceWeaponTargetLifeMethods.N,C=SourceWeaponTargetLifeMethods.C,W=SourceWeaponTargetLifeMethods.W,B=SourceWeaponTargetLifeMethods.B,PC=SourceWeaponTargetLifeMethods.PC,V=SourceWeaponTargetLifeMethods.V,FIELD=SourceWeaponTargetLifeMethods.FIELD;static void need(boolean b,String s){if(!b)throw new AssertionError(s);}static void load(MethodNode m,MethodInsnNode call,int slot,int opcode){var n=FreezeAcceptedMethods.prev(call);need(n instanceof VarInsnNode x&&x.var==slot&&x.getOpcode()==opcode,"exact first Context operand "+slot);m.instructions.remove(n);}static void body(ClassNode c,MethodNode old,ClassNode d,MethodNode now){need(Arrays.equals(SourceNpcFirstViewDelta.body(c,old,old.name),SourceNpcFirstViewDelta.body(d,now,old.name)),"whole original inverse "+c.name+"."+old.name);}
 static void existing(MethodNode m){for(var node:m.instructions.toArray())if(m.instructions.contains(node)&&node instanceof MethodInsnNode call&&call.owner.equals(N)){switch(call.name){case "binding"->{load(m,call,1,ALOAD);call.owner=P+"NativePlayerCommit$Binding";call.name="capture";call.desc="(L"+PC+";)L"+P+"NativePlayerCommit$Binding;";}case "reserve"->{load(m,call,1,ALOAD);call.owner=V;call.desc="(L"+PC+";)L"+V+"$Receipt;";}case "reuse"->{load(m,call,1,ALOAD);load(m,call,0,ALOAD);m.instructions.remove(call);}case "admit"->{load(m,call,2,ILOAD);load(m,call,1,ALOAD);load(m,call,0,ALOAD);var branch=FreezeSourceTargetDelta.next(call);var zero=FreezeSourceTargetDelta.next(branch);var ret=FreezeSourceTargetDelta.next(zero);need(branch.getOpcode()==IFNE&&zero.getOpcode()==ICONST_0&&ret.getOpcode()==IRETURN,"first target admission prefix");for(var n:List.of(call,branch,zero,ret))m.instructions.remove(n);}case "scene"->{call.owner=C;call.desc="()Z";call.setOpcode(INVOKEVIRTUAL);}case "prepare"->{load(m,call,4,ALOAD);call.owner=B;call.desc="(L"+PC+";L"+P+"BattleCompanion;)L"+P+"SourceNpcPhysicalStats;";}case "runRequest"->{load(m,call,0,ALOAD);m.instructions.remove(call);}default->throw new AssertionError("unreviewed existing method port "+call.name);}}}
 static void first(MethodNode m,MethodNode original){int ports=0;for(var node:m.instructions.toArray())if(node instanceof MethodInsnNode call){if(call.owner.equals(N)){switch(call.name){case "firstRequest"->{load(m,call,4,ALOAD);load(m,call,3,ALOAD);call.owner=P+"Protocol";call.name="attackSpellRequest";call.desc="([B)L"+P+"Protocol$AttackSpellRequest;";}case "context"->{load(m,call,3,ALOAD);var x=new org.objectweb.asm.tree.InsnList();x.add(new TypeInsnNode(NEW,C));x.add(new InsnNode(DUP));x.add(new VarInsnNode(ALOAD,0));m.instructions.insertBefore(call,x);call.owner=C;call.name="<init>";call.desc="(L"+PC+";)V";call.setOpcode(INVOKESPECIAL);}case "members"->{load(m,call,3,ALOAD);call.owner=P+"GameHub";call.name="roomCombatants";call.desc="(J)Ljava/util/List;";call.setOpcode(INVOKEVIRTUAL);}case "next"->{load(m,call,3,ALOAD);call.owner=P+"NativeCancellationNpcMaterialAction";call.name="dispatch";call.desc="(L"+PC+";[BL"+P+"NativeSelfCastAction$Task;)V";}case "phase"->{load(m,call,3,ALOAD);m.instructions.remove(call);}default->throw new AssertionError("unreviewed first dispatch port "+call.name);}ports++;}else if(call.owner.equals(P+"NativeSourceTargetNegativeReserve")&&call.name.equals("reserve")){load(m,call,3,ALOAD);call.owner=V;call.desc="(L"+PC+";)L"+V+"$Receipt;";ports++;}}need(ports==7,"seven explicit first-dispatch ports");for(var node:m.instructions){if(node instanceof VarInsnNode x&&x.var>=5)x.var-=2;if(node instanceof IincInsnNode x&&x.var>=5)x.var-=2;}m.desc=original.desc;m.maxLocals=original.maxLocals;}
 static void prepare(MethodNode m,MethodNode old){int ports=0;for(var node:m.instructions.toArray())if(node instanceof MethodInsnNode call&&call.owner.equals(N)&&call.name.equals("snapshot")){load(m,call,2,ALOAD);call.owner=P+"BattleCompanion";call.desc="()L"+P+"BattleCompanion$Snapshot;";call.setOpcode(INVOKEVIRTUAL);var n=FreezeSourceTargetDelta.next(call);for(int op:new int[]{DUP,IFNONNULL,POP,POP,ACONST_NULL,ARETURN}){need(n!=null&&n.getOpcode()==op,"bounded null snapshot early return");var next=FreezeSourceTargetDelta.next(n);m.instructions.remove(n);n=next;}ports++;}need(ports==1,"one original pre-query snapshot port");for(var node:m.instructions){if(node instanceof VarInsnNode x&&x.var>=3)x.var--;if(node instanceof IincInsnNode x&&x.var>=3)x.var--;}m.desc=old.desc;m.maxLocals=old.maxLocals;}
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[0]);var jar=new JarFile(a[1])){var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(old.entries())){names.add(e.getName());var now=jar.getJarEntry(e.getName());need(now!=null,"all original entries retained");if(!Arrays.equals(old.getInputStream(e).readAllBytes(),jar.getInputStream(now).readAllBytes()))changed.add(e.getName());}need(changed.equals(Set.of(C+".class",W+".class",B+".class")),"three exact original owners");var added=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName()))added.add(e.getName());need(added.equals(Set.of(N+".class")),"one fieldless first Context helper");int methods=0,siblings=0;for(var owner:SourceWeaponTargetLifeMethods.OWNERS){var before=FreezeSourceTargetDelta.read(old,owner);var after=FreezeSourceTargetDelta.read(jar,owner);if(owner.equals(C)){var f=after.fields.stream().filter(x->x.name.equals(FIELD)).findFirst().orElseThrow();need(f.desc.equals("Ljava/lang/Object;")&&f.access==(ACC_TRANSIENT|ACC_VOLATILE),"bounded retired Context marker only");after.fields.remove(f);}need(before.fields.size()==after.fields.size()&&after.methods.size()==before.methods.size()+(owner.equals(W)?2:owner.equals(B)?1:0),"original members plus two dispatch and one prepare sibling");for(int i=0;i<before.fields.size();i++){var f=before.fields.get(i);var g=after.fields.get(i);need(f.name.equals(g.name)&&f.desc.equals(g.desc)&&f.access==g.access&&Objects.equals(f.signature,g.signature)&&Objects.equals(f.value,g.value),"original fields exact");}for(var original:before.methods){var name=owner.equals(W)&&original.name.equals("dispatch")?SourceWeaponTargetLifeMethods.ORIGINAL:original.name;var now=after.methods.stream().filter(x->x.name.equals(name)&&x.desc.equals(original.desc)).findFirst().orElseThrow();if(owner.equals(W)&&!name.equals(SourceWeaponTargetLifeMethods.ORIGINAL))existing(now);body(before,original,after,now);methods++;}
 if(owner.equals(W)){var original=before.methods.stream().filter(x->x.name.equals("dispatch")).findFirst().orElseThrow();var first=after.methods.stream().filter(x->x.name.equals(SourceWeaponTargetLifeMethods.FIRST)).findFirst().orElseThrow();first(first,original);body(before,original,after,first);var wrapper=after.methods.stream().filter(x->x.name.equals("dispatch")).findFirst().orElseThrow();var nodes=Arrays.stream(wrapper.instructions.toArray()).filter(x->x.getOpcode()>=0).toList();need(nodes.size()==5&&nodes.get(0)instanceof VarInsnNode x&&x.var==0&&nodes.get(1)instanceof VarInsnNode y&&y.var==1&&nodes.get(2)instanceof VarInsnNode z&&z.var==2&&nodes.get(3)instanceof MethodInsnNode call&&call.owner.equals(N)&&call.name.equals("dispatch")&&nodes.get(4).getOpcode()==RETURN&&wrapper.tryCatchBlocks.isEmpty(),"one original-signature wrapper only");siblings+=2;}
 if(owner.equals(B)){var original=before.methods.stream().filter(x->x.name.equals("prepare")).findFirst().orElseThrow();var sibling=after.methods.stream().filter(x->x.name.equals("nativeSourceWeaponFirstPrepare")).findFirst().orElseThrow();prepare(sibling,original);body(before,original,after,sibling);siblings++;}}
 need(siblings==3,"three complete original dispatch/prepare siblings");System.out.println("PASS independent weapon target life inverse: "+methods+" original methods,1 dispatch wrapper,3 complete original dispatch/prepare siblings,8 selected old call sites,1 bounded Context marker; original Source query/cost/RNG/status/receipt/publication/handlers retained");}}
}
